window.AYAYA_N3_WORDS = window.AYAYA_N3_CODEX_VOCAB.entries.map((entry) => [entry.headword, entry.reading, entry.meaning_zh, entry.examples[0].ja, entry.examples[0].zh]);

window.AYAYA_N3_TATOEBA_EXAMPLES = (() => {
  const candidates = new Map();
  for (const entry of window.AYAYA_N3_CODEX_VOCAB.entries) {
    const keys = new Set([
      entry.headword,
      ...(entry.variants || []),
      ...String(entry.source_form || "").split(";"),
    ].map((key) => key.trim()).filter(Boolean));
    for (const key of keys) {
      const matches = candidates.get(key) || [];
      matches.push(entry.examples);
      candidates.set(key, matches);
    }
  }
  return Object.fromEntries(
    [...candidates.entries()]
      .filter(([, matches]) => matches.length === 1)
      .map(([key, [examples]]) => [key, examples]),
  );
})();
